        Ok(None) => (StatusCode::NOT_FOUND, Json(serde_json::json!({"error":"not found"}))).into_response(),
        Err(error) => internal_error(error),
    }
}

fn action_succeeded(path: &FsPath, game_id: i64, action: &str) -> rusqlite::Result<bool> {
    let mut connection = open_database(path)?;
    match action {
        "start" => {
            Ok(connection.execute(
                "UPDATE games SET status = 'open', current_position = 0
                 WHERE id = ?1 AND status = 'waiting'
                   AND EXISTS(SELECT 1 FROM game_questions WHERE game_id = ?1)",
                [game_id],
            )? == 1)
        }
        "finish" => Ok(connection.execute(
            "UPDATE games SET status = 'closed' WHERE id = ?1 AND status = 'open'",
            [game_id],
        )? == 1),
        "next" => {
            let transaction = connection.transaction()?;
            let row: Option<(String, i64, i64)> = transaction
                .query_row(
                    "SELECT status, current_position,
                            (SELECT COUNT(*) FROM game_questions WHERE game_id = games.id)
                     FROM games WHERE id = ?1",
                    [game_id],
                    |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
                )
                .optional()?;
            let Some((status, position, total)) = row else {
                return Ok(false);
            };
            if status != "closed" || total == 0 {
                return Ok(false);
            }
            if position + 1 < total {
                transaction.execute(
                    "UPDATE games SET status = 'open', current_position = ?2
                     WHERE id = ?1 AND status = 'closed' AND current_position = ?3",
                    params![game_id, position + 1, position],
                )?;
            } else {
                transaction.execute(
                    "UPDATE games SET status = 'over'
                     WHERE id = ?1 AND status = 'closed' AND current_position = ?2",
                    params![game_id, position],
                )?;
            }
            let changed = transaction.changes() == 1;
            transaction.commit()?;
            Ok(changed)
        }
        _ => Ok(false),
    }
}

pub(super) async fn moderator_game_action(
    State(state): State<AppState>,
    Path(game_id): Path<i64>,
    Form(form): Form<GameActionForm>,
) -> Response {
    if !super::csrf_valid(&state, &form.csrf) {
        return csrf_error();
    }
    match action_succeeded(&state.db_path, game_id, &form.action) {
        Ok(true) => StatusCode::NO_CONTENT.into_response(),
        Ok(false) => StatusCode::CONFLICT.into_response(),
        Err(error) => internal_error(error),
    }
}

fn render_option_list(options: &[GameOptionState], with_results: bool) -> String {
    let mut html = String::new();
    for option in options {
        html.push_str("<li>");
        html.push_str(&escape_html(&option.text));
        if with_results {
            html.push_str(&format!(
                " <span class=\"option-result-count\">Answers: {}</span>",
                option.answers.unwrap_or(0)
            ));
            if option.correct == Some(true) {
                html.push_str(" <strong class=\"correct-label\">Correct</strong>");
            }
        }
        html.push_str("</li>");
    }
    html
}

fn game_action_form(csrf: &str, action: &str, label: &str, button_id: Option<&str>) -> String {
    let id = button_id
        .map(|value| format!(" id=\"{value}\""))
        .unwrap_or_default();
    format!(
        "<form class=\"game-action\" method=\"post\" action=\"/moderate/games/{{GAME_ID}}/action\"><input type=\"hidden\" name=\"csrf\" value=\"{}\"><input class=\"game-action-name\" type=\"hidden\" name=\"action\" value=\"{action}\"><button class=\"btn btn--pink btn--lg\" type=\"submit\"{id}>{label}</button></form>",
        escape_html(csrf)
    )
}

fn render_moderator_game_page(
    state: &AppState,
    game_id: i64,
    game: &ModeratorGameState,
) -> String {
    let active_waiting = game.status == "waiting";
    let active_open = game.status == "open";
    let active_closed = game.status == "closed";
    let active_over = game.status == "over";
    let question_number = game.question_number.unwrap_or(1);
    let question_text = game
        .question_text
        .as_deref()
        .map(escape_html)
        .unwrap_or_default();
    let join_link = escape_html(&game.join_url);
    let qr_svg = qr_svg(&game.join_url);
    let open_options = render_option_list(&game.options, false);
    let closed_options = render_option_list(&game.options, true);
    let next_label = if game.question_number.unwrap_or(0) >= game.question_count {
        "End quiz"
    } else {
        "Next"
    };
    let mut start_form = game_action_form(&state.csrf_token, "start", "Start", None);
    start_form = start_form.replace("{GAME_ID}", &game_id.to_string());
    let mut finish_form = game_action_form(&state.csrf_token, "finish", "Finish", None);
    finish_form = finish_form.replace("{GAME_ID}", &game_id.to_string());
    let mut next_form = game_action_form(&state.csrf_token, "next", next_label, Some("next-button"));
    next_form = next_form.replace("{GAME_ID}", &game_id.to_string());
    let body = format!(
        "<div class=\"game-screen\" id=\"game-screen\" data-game-id=\"{game_id}\">
          <section id=\"waiting-stage\" class=\"game-stage\"{}>
            <h1 id=\"screen-title\">{}</h1>
            <p class=\"game-kicker\">Join at</p><p id=\"join-link\" class=\"join-link\">{join_link}</p>
            <div id=\"qr-code\" class=\"qr-code\">{qr_svg}</div>
            <p id=\"player-count\" class=\"game-counter\">Players: {}</p>
            {start_form}
          </section>
          <section id=\"open-stage\" class=\"game-stage\"{}>
            <p id=\"question-progress\" class=\"game-kicker\">Question {question_number} of {}</p>
            <h1 id=\"open-question\">{question_text}</h1>
            <ol id=\"open-options\" class=\"game-option-list\">{open_options}</ol>
            <p id=\"answer-count\" class=\"game-counter\">Answers: {} / {}</p>
            {finish_form}
          </section>
          <section id=\"closed-stage\" class=\"game-stage\"{}>
            <p id=\"closed-progress\" class=\"game-kicker\">Question {question_number} of {}</p>
            <h1 id=\"closed-question\">{question_text}</h1>
            <ol id=\"closed-options\" class=\"game-option-list game-option-list--results\">{closed_options}</ol>
            {next_form}
          </section>
          <section id=\"over-stage\" class=\"game-stage\"{}><h1>The quiz is over</h1></section>
        </div>
        <script>{MODERATOR_SCRIPT}</script>",
        if active_waiting { "" } else { " hidden" },
        escape_html(&game.title),
        game.players,
        if active_open { "" } else { " hidden" },
        game.question_count,
        game.answered,
        game.players,
        if active_closed { "" } else { " hidden" },
        game.question_count,
        if active_over { "" } else { " hidden" },
    );
    page(&game.title, &body)
}

const MODERATOR_SCRIPT: &str = r#"
(() => {
  const screen = document.getElementById('game-screen');
  const gameId = screen.dataset.gameId;
  const base = `/moderate/games/${gameId}`;
  const byId = (id) => document.getElementById(id);
  const show = (id, visible) => { byId(id).hidden = !visible; };
  function replaceOptions(id, options, results) {
    const list = byId(id);
    list.replaceChildren();
    for (const option of options || []) {
      const item = document.createElement('li');
      item.append(document.createTextNode(option.text));
      if (results) {
        const count = document.createElement('span');
        count.className = 'option-result-count';
        count.textContent = `Answers: ${option.answers || 0}`;
        item.append(document.createTextNode(' '), count);
        if (option.correct) {
          const correct = document.createElement('strong');
          correct.className = 'correct-label';
          correct.textContent = 'Correct';
          item.append(document.createTextNode(' '), correct);
        }
      }
      list.append(item);
    }
  }
  function render(state) {
    byId('screen-title').textContent = state.title;
    byId('join-link').textContent = state.join_url;
    byId('player-count').textContent = `Players: ${state.players}`;
    const hasQuestion = state.question_number !== null;
    const progress = hasQuestion ? `Question ${state.question_number} of ${state.question_count}` : '';
    byId('question-progress').textContent = progress;
    byId('closed-progress').textContent = progress;
    byId('open-question').textContent = state.question_text || '';
    byId('closed-question').textContent = state.question_text || '';
    byId('answer-count').textContent = `Answers: ${state.answered} / ${state.players}`;
    replaceOptions('open-options', state.options, false);
    replaceOptions('closed-options', state.options, true);
    show('waiting-stage', state.status === 'waiting');
    show('open-stage', state.status === 'open');
    show('closed-stage', state.status === 'closed');
    show('over-stage', state.status === 'over');
    const next = byId('next-button');
    const action = next.closest('form').querySelector('input[name="action"]');
    if (action) action.value = state.question_number >= state.question_count ? 'next' : 'next';
    next.textContent = state.question_number >= state.question_count ? 'End quiz' : 'Next';
  }
  async function refresh() {
    try {
      const response = await fetch(`${base}/state`, {cache: 'no-store'});
      if (response.ok) render(await response.json());
    } catch (_) { /* a short Wi-Fi interruption is recovered on the next poll */ }
  }
  document.querySelectorAll('form.game-action').forEach((form) => {
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      const button = form.querySelector('button');
      if (button) button.disabled = true;
      const fields = new URLSearchParams();
      for (const [key, value] of new FormData(form)) fields.append(key, value);
      try {
        const response = await fetch(form.action, {
          method: 'POST',
          headers: {'Content-Type': 'application/x-www-form-urlencoded'},
          body: fields.toString(),
          cache: 'no-store'
        });
        if (response.ok) await refresh();
      } catch (_) { /* the moderator may retry after connectivity returns */ }
      if (button) button.disabled = false;
    });
  });
  refresh();
  window.setInterval(refresh, 1200);
})();
"#;

fn qr_svg(value: &str) -> String {
    let Ok(code) = QrCode::new(value.as_bytes()) else {
        return String::new();
    };
    let width = code.width();
    let quiet = 4usize;
    let dimension = width + quiet * 2;
    let mut svg = format!(
        "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 {dimension} {dimension}\" role=\"img\" aria-label=\"QR code for join link\" shape-rendering=\"crispEdges\"><rect width=\"{dimension}\" height=\"{dimension}\" fill=\"white\"/>"
    );
    for y in 0..width {
        for x in 0..width {
            if code[(x, y)] == QrColor::Dark {
                svg.push_str(&format!(
                    "<rect x=\"{}\" y=\"{}\" width=\"1\" height=\"1\" fill=\"#0d0640\"/>",
                    x + quiet,
                    y + quiet
                ));
            }
        }
    }
    svg.push_str("</svg>");
    svg
}
