        Ok(connection) => connection,
        Err(error) => return internal_error(error),
    };
    let game: Option<(i64, String, String, i64)> = match connection
        .query_row(
            "SELECT id, quiz_title, status, current_position FROM games WHERE code = ?1",
            [&code],
