}

fn find_player(path: &FsPath, game_id: i64, token: &str) -> rusqlite::Result<Option<(i64, String)>> {
    let connection = open_database(path)?;
    connection
        .query_row(
            "SELECT id, name FROM players WHERE game_id = ?1 AND token = ?2",
            params![game_id, token],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()
}

fn load_player_state(
    path: &FsPath,
    code: &str,
    token: &str,
) -> rusqlite::Result<Option<PlayerGameState>> {
    let connection = open_database(path)?;
    let game: Option<(i64, String, i64, String)> = connection
        .query_row(
            "SELECT id, status, current_position, quiz_title FROM games WHERE code = ?1",
            [code],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .optional()?;
    let Some((game_id, status, current_position, _title)) = game else {
        return Ok(None);
    };
    let player: Option<(i64, String)> = connection
        .query_row(
            "SELECT id, name FROM players WHERE game_id = ?1 AND token = ?2",
            params![game_id, token],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?;
    let Some((player_id, player_name)) = player else {
        return Ok(None);
    };
    let question_count: i64 = connection.query_row(
        "SELECT COUNT(*) FROM game_questions WHERE game_id = ?1",
        [game_id],
        |row| row.get(0),
    )?;
    let mut state = PlayerGameState {
        status: status.clone(),
        player_name,
        question_number: None,
        question_count,
        question: None,
        selected_option: None,
        feedback: None,
    };
    if current_position < 0 {
        return Ok(Some(state));
    }
    state.question_number = Some(current_position + 1);
    let question: Option<(i64, String)> = connection
        .query_row(
            "SELECT id, body FROM game_questions WHERE game_id = ?1 AND position = ?2",
            params![game_id, current_position],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .optional()?;
    let Some((question_id, body)) = question else {
        return Ok(Some(state));
    };
    if status == "open" {
        let selected: Option<i64> = connection
            .query_row(
                "SELECT option_id FROM answers WHERE player_id = ?1 AND game_question_id = ?2",
                params![player_id, question_id],
                |row| row.get(0),
            )
            .optional()?;
        let mut statement = connection.prepare(
            "SELECT id, body FROM game_options WHERE game_question_id = ?1 ORDER BY position, id",
        )?;
        let options = statement
            .query_map([question_id], |row| {
                Ok(PlayerOption {
                    id: row.get(0)?,
                    text: row.get(1)?,
                })
            })?
            .collect::<rusqlite::Result<Vec<_>>>()?;
        state.selected_option = selected;
        state.question = Some(PlayerQuestion {
            id: question_id,
            text: body,
            options,
        });
    } else if status == "closed" {
        let correct: Option<bool> = connection
            .query_row(
                "SELECT option.is_correct
                 FROM answers answer
                 JOIN game_options option
                   ON option.id = answer.option_id AND option.game_question_id = answer.game_question_id
                 WHERE answer.player_id = ?1 AND answer.game_question_id = ?2",
                params![player_id, question_id],
                |row| row.get::<_, i64>(0).map(|correct| correct != 0),
            )
            .optional()?;
        state.feedback = Some(match correct {
            None => "No answer".to_owned(),
            Some(true) => "Correct!".to_owned(),
            Some(false) => "Wrong!".to_owned(),
        });
    }
    Ok(Some(state))
}

pub(super) async fn player_game_state(
    State(state): State<AppState>,
    Path(raw_code): Path<String>,
    headers: HeaderMap,
) -> Response {
    let Some(code) = canonical_code(&raw_code) else {
        return (StatusCode::NOT_FOUND, Json(serde_json::json!({"error":"not found"}))).into_response();
    };
    let Some(token) = player_cookie_token(&headers, &code) else {
        return (StatusCode::UNAUTHORIZED, Json(serde_json::json!({"error":"join first"}))).into_response();
    };
    match load_player_state(&state.db_path, &code, &token) {
        Ok(Some(game_state)) => json_response(game_state),
        Ok(None) => (StatusCode::UNAUTHORIZED, Json(serde_json::json!({"error":"join first"}))).into_response(),
        Err(error) => internal_error(error),
    }
}

pub(super) async fn submit_answer(
    State(state): State<AppState>,
    Path(raw_code): Path<String>,
    headers: HeaderMap,
    Form(form): Form<AnswerForm>,
) -> Response {
    let Some(code) = canonical_code(&raw_code) else {
        return StatusCode::NOT_FOUND.into_response();
    };
    let Some(token) = player_cookie_token(&headers, &code) else {
        return StatusCode::UNAUTHORIZED.into_response();
    };
    let mut connection = match open_database(&state.db_path) {
        Ok(connection) => connection,
        Err(error) => return internal_error(error),
    };
    let transaction = match connection.transaction() {
        Ok(transaction) => transaction,
        Err(error) => return internal_error(error),
    };
    let player: Option<(i64, i64, i64)> = match transaction
        .query_row(
            "SELECT player.id, game.id, game.current_position
             FROM players player JOIN games game ON game.id = player.game_id
             WHERE game.code = ?1 AND player.token = ?2 AND game.status = 'open'",
            params![code, token],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .optional()
    {
        Ok(player) => player,
        Err(error) => return internal_error(error),
    };
    let Some((player_id, game_id, position)) = player else {
        return StatusCode::CONFLICT.into_response();
    };
    let question_id: Option<i64> = match transaction
        .query_row(
            "SELECT id FROM game_questions WHERE game_id = ?1 AND position = ?2",
            params![game_id, position],
            |row| row.get(0),
        )
        .optional()
    {
        Ok(question) => question,
        Err(error) => return internal_error(error),
    };
    let Some(question_id) = question_id else {
        return StatusCode::CONFLICT.into_response();
    };
    let valid_option: bool = match transaction.query_row(
        "SELECT EXISTS(SELECT 1 FROM game_options WHERE id = ?1 AND game_question_id = ?2)",
        params![form.option_id, question_id],
        |row| row.get(0),
    ) {
        Ok(valid) => valid,
        Err(error) => return internal_error(error),
    };
    if !valid_option {
        return StatusCode::BAD_REQUEST.into_response();
    }
    if let Err(error) = transaction.execute(
        "INSERT INTO answers(player_id, game_question_id, option_id)
         VALUES (?1, ?2, ?3)
         ON CONFLICT(player_id, game_question_id) DO UPDATE SET
             option_id = excluded.option_id, updated_at = CURRENT_TIMESTAMP",
        params![player_id, question_id, form.option_id],
    ) {
        return internal_error(error);
    }
    if let Err(error) = transaction.commit() {
        return internal_error(error);
    }
    json_response(AnswerAck { ok: true })
}

fn render_player_page(code: &str, initial: PlayerGameState) -> String {
    let initial_html = render_player_state_html(&initial);
    let code_json = serde_json::to_string(code).unwrap_or_else(|_| "\"\"".to_owned());
    let body = format!(
        "<section class=\"player-card\"><div id=\"player-state\">{initial_html}</div></section><script>const GAME_CODE={code_json};{PLAYER_SCRIPT}</script>",
    );
    player_document("Play", &body)
}

fn render_player_state_html(state: &PlayerGameState) -> String {
    if state.status == "over" {
        return "<h1>The quiz is over</h1>".to_owned();
    }
    let mut content = format!("<h1>Hi, {}!</h1>", escape_html(&state.player_name));
    match state.status.as_str() {
        "waiting" => content.push_str("<p class=\"player-waiting\">Waiting for the quiz to start</p>"),
        "open" => {
            if let Some(question) = &state.question {
                content.push_str(&format!(
                    "<p class=\"game-kicker\">Question {} of {}</p><h2>{}</h2><div class=\"player-options\">",
                    state.question_number.unwrap_or(0),
                    state.question_count,
                    escape_html(&question.text)
                ));
                for option in &question.options {
                    let selected = state.selected_option == Some(option.id);
                    content.push_str(&format!(
                        "<button class=\"btn player-option{}\" type=\"button\" data-option-id=\"{}\" aria-pressed=\"{}\">{}{} </button>",
                        if selected { " is-selected" } else { "" },
                        option.id,
                        selected,
                        escape_html(&option.text),
                        if selected { " <span>Your answer</span>" } else { "" },
                    ));
                }
                content.push_str("</div>");
            }
        }
        "closed" => content.push_str(&format!(
            "<p class=\"player-feedback\">{}</p>",
            escape_html(state.feedback.as_deref().unwrap_or("No answer"))
        )),
        _ => content.push_str("<p>Waiting for the quiz to start</p>"),
    }
    content
}

const PLAYER_SCRIPT: &str = r#"
(() => {
  const root = document.getElementById('player-state');
  const base = `/play/${GAME_CODE}`;
  let latest = null;
  let pendingSelection = null;
  let pendingQuestion = null;
  const escapeHtml = (value) => String(value).replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  }[character]));
  function render(state) {
    latest = state;
    if (state.status === 'over') {
      root.innerHTML = '<h1>The quiz is over</h1>';
      return;
    }
    let html = `<h1>Hi, ${escapeHtml(state.player_name)}!</h1>`;
    if (state.status === 'waiting') {
      html += '<p class="player-waiting">Waiting for the quiz to start</p>';
    } else if (state.status === 'open' && state.question) {
      html += `<p class="game-kicker">Question ${state.question_number} of ${state.question_count}</p><h2>${escapeHtml(state.question.text)}</h2><div class="player-options">`;
      const selectedId = pendingSelection !== null && pendingQuestion === state.question.id
        ? pendingSelection : state.selected_option;
      for (const option of state.question.options) {
        const selected = selectedId === option.id;
        html += `<button class="btn player-option${selected ? ' is-selected' : ''}" type="button" data-option-id="${option.id}" aria-pressed="${selected}">${escapeHtml(option.text)}${selected ? ' <span>Your answer</span>' : ''}</button>`;
      }
      html += '</div>';
    } else if (state.status === 'closed') {
      pendingSelection = null;
      pendingQuestion = null;
      html += `<p class="player-feedback">${escapeHtml(state.feedback || 'No answer')}</p>`;
    }
    root.innerHTML = html;
    root.querySelectorAll('button[data-option-id]').forEach((button) => {
      button.addEventListener('click', () => choose(Number(button.dataset.optionId), state.question.id));
    });
  }
  async function refresh() {
    try {
      const response = await fetch(`${base}/state`, {cache: 'no-store'});
      if (response.ok) render(await response.json());
    } catch (_) { /* keep the last screen during a temporary conference Wi-Fi gap */ }
  }
  async function choose(optionId, questionId) {
    pendingSelection = optionId;
    pendingQuestion = questionId;
    render(latest);
    const fields = new URLSearchParams({option_id: String(optionId)});
    try {
      const response = await fetch(`${base}/answer`, {
        method: 'POST',
        headers: {'Content-Type': 'application/x-www-form-urlencoded'},
        body: fields.toString(),
        cache: 'no-store'
      });
      if (!response.ok) {
        pendingSelection = null;
        pendingQuestion = null;
      }
      await refresh();
    } catch (_) {
      /* the selection remains visible and can be submitted again by tapping */
    }
  }
  root.addEventListener('click', (event) => {
    const button = event.target.closest('button[data-option-id]');
    if (button && latest && latest.question) {
      choose(Number(button.dataset.optionId), latest.question.id);
    }
  });
  refresh();
  window.setInterval(refresh, 1200);
})();
"#;
