fn load_quiz(path: &FsPath, quiz_id: i64) -> rusqlite::Result<Option<Quiz>> {
    let connection = open_database(path)?;
    let quiz = connection
        .query_row(
            "SELECT id, title FROM quizzes WHERE id = ?1",
            [quiz_id],
            |row| {
                Ok(Quiz {
                    id: row.get(0)?,
                    title: row.get(1)?,
                    questions: Vec::new(),
                })
            },
        )
        .optional()?;
    let Some(mut quiz) = quiz else {
        return Ok(None);
    };

    let mut statement = connection.prepare(
        "SELECT id, body, active, position FROM questions
         WHERE quiz_id = ?1 ORDER BY position, id",
    )?;
    let questions = statement
        .query_map([quiz_id], |row| {
            Ok(Question {
                id: row.get(0)?,
                body: row.get(1)?,
                active: row.get::<_, i64>(2)? != 0,
                options: Vec::new(),
            })
        })?
        .collect::<rusqlite::Result<Vec<_>>>()?;
    drop(statement);

    for mut question in questions {
        let mut option_statement = connection.prepare(
            "SELECT body, is_correct FROM options
             WHERE question_id = ?1 ORDER BY position, id",
        )?;
        Ok(Some(quiz)) => {
            let transfer = transfer_from_quiz(&quiz);
            match serde_json::to_string_pretty(&transfer) {
                Ok(json) => {
                    let content = format!(
                        "<div class=\"breadcrumbs\"><a href=\"/moderate/quizzes/{}\">← {}</a></div><div class=\"page-head\"><div><h1>Export quiz</h1><p class=\"meta\">Copy this JSON to move the quiz to another Quizzy app.</p></div></div><pre class=\"quiz-json\">{}</pre>",
                        quiz.id,
                        escape_html(&quiz.title),
                        escape_html(&json)
                    );
                    Html(page("Export quiz", &content)).into_response()
                }
                Err(error) => internal_error(error),
            }
        }
        Ok(None) => not_found(),
        Err(error) => internal_error(error),
    }
}

async fn edit_quiz(State(state): State<AppState>, Path(quiz_id): Path<i64>) -> Response {
    match load_quiz(&state.db_path, quiz_id) {
        Ok(Some(quiz)) => {
            Html(render_quiz_form(&state, Some(quiz.id), &quiz.title, &[])).into_response()
        }
        Ok(None) => not_found(),
        Err(error) => internal_error(error),
    }
}

async fn update_quiz(
    State(state): State<AppState>,
    Path(quiz_id): Path<i64>,
    Form(form): Form<QuizForm>,
) -> Response {
    if !csrf_valid(&state, &form.csrf) {
        return csrf_error();
    }
    let Ok(Some(_)) = load_quiz(&state.db_path, quiz_id) else {
        return not_found();
    };
    let title = form.title.trim();
    if title.is_empty() {
        return Html(render_quiz_form(
            &state,
            Some(quiz_id),
            &form.title,
            &["Title is required".to_owned()],
        ))
        .into_response();
    }
    match open_database(&state.db_path).and_then(|connection| {
        connection.execute(
            "UPDATE quizzes SET title = ?1 WHERE id = ?2",
            params![title, quiz_id],
        )
    }) {
        Ok(_) => Redirect::to(&format!("/moderate/quizzes/{quiz_id}")).into_response(),
        Err(error) => internal_error(error),
    }
}

async fn delete_quiz(
    State(state): State<AppState>,
    Path(quiz_id): Path<i64>,
    Form(form): Form<CsrfForm>,
) -> Response {
    if !csrf_valid(&state, &form.csrf) {
        return csrf_error();
    }
    match open_database(&state.db_path)
        .and_then(|connection| connection.execute("DELETE FROM quizzes WHERE id = ?1", [quiz_id]))
    {
        Ok(0) => not_found(),
        Ok(_) => Redirect::to("/moderate").into_response(),
        Err(error) => internal_error(error),
    }
}

